  function wholeSchoolReport(mode){
    if(!data.students.length){alert("Register students before creating the whole-school report.");return}
    const styles='@page{size:A4 landscape;margin:12mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#172b49;margin:24px}h1,h2{color:#16345c}h2{margin-top:28px;border-bottom:2px solid #31577e;padding-bottom:6px}.meta{color:#596a80}table{width:100%;border-collapse:collapse;margin:12px 0 24px}th{background:#31577e;color:#fff;text-align:left;padding:8px}td{border:1px solid #aab6c4;padding:7px}.summary{padding:10px;background:#eef3f8;margin:10px 0}.pending{color:#9a5b00}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}';
    let body=`<h1>${esc(data.school)} — Whole-school examination overview</h1><p class="meta">${esc(data.term)} · ${esc(data.year)} · Generated ${new Date().toLocaleDateString()}</p>`;
    for(const lev of ["primary","secondary"]){const kids=data.students.filter(s=>s.level===lev);const ranked=calc.rankStudents(kids.map(s=>calculateUniqueStudent(s,lev)),lev);const complete=ranked.filter(s=>s.marksComplete!==false).length;body+=`<h2>${lev==="primary"?"Primary":"Secondary"}</h2><div class="summary">Learners: ${kids.length} · Complete: ${complete} · Pending marks: ${kids.length-complete}</div><table><thead><tr><th>Position</th><th>Student</th><th>Student no.</th><th>Class / Form</th><th>Total</th><th>Overall</th><th>${lev==="primary"?"Units":"Subjects passed"}</th></tr></thead><tbody>${ranked.map(s=>`<tr><td>${s.position?"#"+s.position:'<span class="pending">Pending</span>'}</td><td>${esc(s.name)}</td><td>${esc(s.studentNo||"—")}</td><td>${esc(s.className)}</td><td>${s.maximum?s.obtained+"/"+s.maximum:"—"}</td><td>${s.percentage===null?"—":s.percentage.toFixed(2)+"%"}</td><td>${lev==="primary"?s.totalUnits:s.passedSubjects}</td></tr>`).join("")||'<tr><td colspan="7">No learners registered at this level.</td></tr>'}</tbody></table>`}
    openReportDocument("Whole-school overview",body,styles,mode);
  }
  function openReportDocument(titleText,body,styles,mode){
    const autoPrint=mode==="print"?"<script>window.onload=()=>setTimeout(()=>window.print(),400)</script>":"";
    const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(titleText)}</title><style>${styles}</style></head><body>${body}${autoPrint}</body></html>`;
    if(mode==="download"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([html],{type:"text/html;charset=utf-8"}));a.download=titleText.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")+".html";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return}
    const w=window.open("","_blank");if(!w){alert("Allow pop-ups to preview or print reports.");return}w.document.open();w.document.write(html);w.document.close();
  }
  function printReports(students,level,overall,cohortSize=students.length,mode="print"){
    if(!students.length){alert("No students match this report selection.");return}
    const primary=level==="primary",accent=primary?"#816a2d":"#31577e",paper=primary?"#fff3cc":"#e4edf7",school=esc(data.school),logo=new URL("assets/school-logo.png",document.baseURI).href;
    const fmt=n=>n==null?"—":Number(n).toFixed(2)+"%";
    const openPrint=(titleText,body,styles)=>openReportDocument(titleText,body,styles,mode);
    const common=`@page{size:A4;margin:8mm}*{box-sizing:border-box}body{font:11px Arial,sans-serif;color:#172b49;margin:0}.sheet{min-height:277mm;padding:9mm;border:4px double #111;margin:0 auto 5mm;background:${paper};page-break-after:always}.sheet:last-child{page-break-after:auto}header{display:flex;gap:16px;align-items:center;border-bottom:2px solid ${accent};padding-bottom:12px;margin-bottom:14px}.crest{width:58px;height:58px;border:3px double ${accent};border-radius:50%;display:grid;place-items:center;font:bold 21px Georgia;color:${accent}}.school-logo{width:92px;height:64px;object-fit:contain;flex:0 0 auto}h1{font:bold 21px Georgia;margin:0;color:#102b59}h2{font:bold 15px Georgia;margin:7px 0 3px;text-transform:uppercase}header p{margin:0;color:#596a80}.student{line-height:2.1;margin-bottom:12px}.student span{margin-left:18px}table{width:100%;border-collapse:collapse;background:white}th{background:${accent};color:white;text-align:left;padding:8px 6px;font-size:9px}td{border:1px solid #9aa8b8;padding:7px 6px;vertical-align:top;line-height:1.4}.totals{padding:12px 8px;background:white;font-size:11px;margin-top:10px;border:1px solid #aab6c4}.comments{margin-top:18px;line-height:2.1}.comments p{border-bottom:1px dotted #778;margin:5px 0}.summary{display:flex;gap:10px;margin:14px 0}.summary div{background:white;padding:10px 14px;border:1px solid #cbd5e1;flex:1}.summary b{display:block;font-size:19px;color:${accent}}.summary small{font-size:9px;color:#596a80}footer{margin-top:18px;border-top:1px solid ${accent};padding-top:9px;text-align:center;letter-spacing:1px;color:#63748b;font-size:9px}.muted{color:#596a80}.low-mark td{color:#b4232e!important;background:#fff0f0}.pass-mark td{color:#1d4ed8!important}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}`;
    if(overall){
      const subjectList=uniqueSubjectTemplates(level);
      const awards=calc.subjectAwards(students,subjectList);
      const ranked=calc.rankStudents(students,level);
      const rows=ranked.map(s=>`<tr><td><b>${s.position}</b></td><td>${esc(s.name)}</td><td>${esc(s.className)}</td><td>${s.obtained.toFixed(2)} / ${s.maximum.toFixed(2)}</td><td>${fmt(s.percentage)}</td><td>${primary?s.totalUnits:s.results.filter(result=>result.percentage!=null&&result.percentage>=50).length}</td></tr>`).join("");
      const awardRows=awards.map(a=>`<tr><td>${esc(a.subject.name)}</td><td>${a.winners.map(x=>esc(x.student.name)).join(", ")||"—"}</td><td>${fmt(a.percentage)}</td></tr>`).join("");
      const avg=ranked.filter(s=>s.percentage!==null);
      const classAvg=avg.length?avg.reduce((n,s)=>n+s.percentage,0)/avg.length:null;
      const body=`<section class="sheet"><header><img class="school-logo" src="${logo}" alt="Double Impact Private College"><div><h1>${school}</h1><h2>Overall Examination Performance Report</h2><p>${esc(data.term)} · ${esc(data.year)} · ${primary?"Primary":"Secondary"} Division</p></div></header><div class="summary"><div><b>${ranked.length}</b><small>LEARNERS INCLUDED</small></div><div><b>${fmt(classAvg)}</b><small>MEAN OVERALL PERCENTAGE</small></div><div><b>${subjectList.length}</b><small>SUBJECTS CONFIGURED</small></div><div><b>${avg.length}</b><small>WITH RECORDED RESULTS</small></div></div><h3>Student ranking</h3><table><thead><tr><th>POSITION</th><th>STUDENT</th><th>CLASS / FORM</th><th>TOTAL MARKS</th><th>OVERALL %</th><th>${primary?"TOTAL UNITS":"SUBJECTS PASSED"}</th></tr></thead><tbody>${rows}</tbody></table><h3 style="margin-top:22px">Subject excellence awards</h3><table><thead><tr><th>SUBJECT</th><th>BEST STUDENT(S)</th><th>BEST AVERAGE</th></tr></thead><tbody>${awardRows}</tbody></table><p class="muted" style="margin-top:18px">Primary ranking: lowest total units first; ties are ordered by overall percentage. Secondary ranking: highest qualifying three-subject band first, then band count and total marks. Confirm the school's tie-break policy before publishing official results.</p><footer>THE EMPIRE OF EXCELLENCE · YOUR SUCCESS IS OUR PRIORITY</footer></section>`;
      openPrint("Overall Examination Report",body,common+`h3{font: bold 13px Georgia;color:#102b59;margin:18px 0 8px}`);
      return;
    }
    const pages=students.map(s=>{const c=data.reportComments[`${data.year}|${data.term}|${s.id}`]||{},attendance=attendanceCounts(s),reportTitle=primary?"Primary School Report":secondaryTrackForClass(s.className)==="zjc"?"ZJC Report Book":"O’Level Report Book";const hasExtraPapers=s.results.some(result=>result.papers.length>2),paperCell=(result,index)=>{const paper=result.papers[index];return paper?(paper.complete===false?"—":esc(paper.obtained??"—"))+" / "+esc(paper.maximum):"—"},otherPapersCell=result=>result.papers.slice(2).map(p=>esc(p.name)+": "+(p.complete===false?"—":esc(p.obtained??"—"))+" / "+esc(p.maximum)).join("<br>");return `<section class="sheet"><header><img class="school-logo" src="${logo}" alt="Double Impact Private College"><div><h1>${school}</h1><h2>${reportTitle}</h2><p>${esc(data.term)} · ${esc(data.year)} · ${esc(s.className||"")}</p></div></header><div class="student"><b>STUDENT:</b> ${esc(s.name)} <span><b>STUDENT NO:</b> ${esc(s.studentNo||"—")}</span><br><b>CLASS / FORM:</b> ${esc(s.className)} <span><b>POSITION:</b> ${s.position||"—"}</span></div><div class="student"><b>POSSIBLE ATTENDANCE:</b> ${attendance.attendancePossible} <span><b>ACTUAL ATTENDANCE:</b> ${attendance.attendanceActual}</span><br><b>CLASS POSITION:</b> ${s.position||"—"} <span><b>OUT OF:</b> ${cohortSize}</span></div><table><thead><tr><th>SUBJECT</th><th>PAPER 1 MARK</th><th>PAPER 2 MARK</th>${hasExtraPapers?"<th>OTHER PAPER MARKS</th>":""}<th>TOTAL MARK</th><th>AVERAGE</th><th>GRADE</th><th>TEACHER COMMENTS</th></tr></thead><tbody>${s.results.map(r=>`<tr class="${r.percentage!=null&&r.percentage<50?"low-mark":r.percentage>=50?"pass-mark":""}"><td>${esc(r.subject.name)}</td><td>${paperCell(r,0)}</td><td>${paperCell(r,1)}</td>${hasExtraPapers?`<td>${otherPapersCell(r)}</td>`:""}<td>${esc(r.obtained??0)} / ${esc(r.maximum??0)}</td><td>${fmt(r.percentage)}</td><td>${primary?r.units:r.grade}</td><td>${esc(c.teacher||"")}</td></tr>`).join("")}</tbody></table><div class="totals"><b>TOTAL MARKS:</b> ${s.obtained} / ${s.maximum} &nbsp; <b>OVERALL:</b> ${fmt(s.percentage)} &nbsp; <b>${primary?"TOTAL UNITS":"SUBJECTS PASSED"}:</b> ${primary?s.totalUnits:s.results.filter(result=>result.percentage!=null&&result.percentage>=50).length}<br><b>NEXT TERM SCHOOL FEES:</b> ${esc(data.fees[data.year+"|"+data.term]||data.fees[data.term]||"—")} &nbsp; <b>NEXT TERM BEGINS:</b> ${esc(data.openingDates[data.year+"|"+data.term]||data.openingDates[data.term]||"—")}</div><div class="comments"><p>Teacher: ${esc(c.teacher||"—")} · ${esc(c.teacherSignature||"Signature: __________________")}</p><p>Principal: ${esc(c.principal||"—")} · ${esc(c.principalSignature||"Signature: __________________")}</p><p>Parent / Guardian: ${esc(c.parent||"—")} · ${esc(c.parentSignature||"Signature: __________________")}</p></div><footer>THE EMPIRE OF EXCELLENCE · YOUR SUCCESS IS OUR PRIORITY</footer></section><section class="sheet"><header><img class="school-logo" src="${logo}" alt="Double Impact Private College"><div><h1>${school}</h1><h2>Attendance and School Record</h2><p>${esc(data.term)} · ${esc(data.year)}</p></div></header><p><b>LEARNER:</b> ${esc(s.name)} · <b>CLASS:</b> ${esc(s.className)}</p><table><thead><tr><th>DATE</th><th>STATUS</th><th>NOTE</th></tr></thead><tbody>${data.attendance.filter(a=>a.studentId===s.id&&(!a.year||(a.year===data.year&&a.term===data.term))).sort((a,b)=>a.date.localeCompare(b.date)).map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(a.status)}</td><td>${esc(a.note||"")}</td></tr>`).join("")||"<tr><td colspan=\"3\">No attendance recorded.</td></tr>"}</tbody></table><footer>SUPPLEMENTARY SCHOOL RECORD</footer></section>`}).join("");
    const anthemRows=[["Ishe komborera Zimbabwe","Blessed be the Land of Zimbabwe"],
      ["Simudzai mureza wedu weZimbabwe","O lift high the banner, the flag of Zimbabwe"],
      ["Yakazvarwa nomoto wechimurenga;","The symbol of freedom proclaiming victory;"],
      ["Neropa zhinji ramagamba","We praise our heroes' sacrifice,"],
      ["Tidzivirire kumhandu dzose;","And vow to keep our land from foes;"],
      ["Ngaikomborerwe nyika yeZimbabwe.","And may the Almighty protect and bless our land."],
      ["Tarisai Zimbabwe nyika yakashongedzwa","O lovely Zimbabwe, so wondrously adorned"],
      ["Namakomo, nehova, zvinoyevedza","With mountains, and rivers cascading, flowing free;"],
      ["Mvura ngainaye, minda ipe mbeza","May we be fed, our labour blessed;"],
      ["Vashandi vatuswe, ruzhinji rugutswe;","And may the Almighty protect and bless our land."],
      ["Ngaikomborerwe nyika yeZimbabwe.",""],
      ["Mwari ropafadzai nyika yeZimbabwe","O God, we beseech Thee to bless our native land;"],
      ["Nyika yamadzitateguru edu tose;","The land of our fathers bestowed upon us all;"],
      ["Kubva Zambezi kusvika Limpopo,","From Zambezi to Limpopo"],
      ["Navatungamiri vave nenduramo;","May leaders be exemplary;"],
      ["Ngaikomborerwe nyika yeZimbabwe.","And may the Almighty protect and bless our land."]
    ].map(row=>"<tr><td>"+esc(row[0])+"</td><td>"+esc(row[1])+"</td></tr>").join("");
    const anthem='<section class="sheet anthem"><header><img class="school-logo" src="'+logo+'" alt="Double Impact Private College"><div><h1>'+school+'</h1><h2>Zimbabwe National Anthem</h2><p>Shona and English versions</p></div></header><img class="flag" src="'+new URL("assets/zimbabwe-flag.png",document.baseURI).href+'" alt="Zimbabwe flag"><table class="anthem-table"><thead><tr><th>SHONA VERSION</th><th>ENGLISH VERSION</th></tr></thead><tbody>'+anthemRows+'</tbody></table><footer>GOD BLESS OUR BEAUTIFUL ZIMBABWE</footer></section>';
    const cover='<section class="sheet cover"><div><img class="school-logo" src="'+logo+'" alt="Double Impact Private College"><h1>'+school+'</h1><h2>Student Report Book</h2><p>'+esc(data.term)+' - '+esc(data.year)+' - '+(primary?'Primary Division':'Secondary Division')+'</p></div><div class="cover-details"><p>This report book belongs to '+school+'.</p><p><b>ADDRESS</b><br>'+esc(data.schoolAddress||'')+'</p><p><b>EMAIL</b> '+esc(data.schoolEmail||'')+'</p><p><b>PHONE</b> '+esc(data.schoolPhone||'')+'</p><p><b>WEBSITE</b> '+esc(data.schoolWebsite||'')+'</p><p>Reports included: '+students.length+'</p></div><footer>THE EMPIRE OF EXCELLENCE - YOUR SUCCESS IS OUR PRIORITY</footer></section>';
    const gradeBands=primary?calc.PRIMARY_BANDS:calc.SECONDARY_BANDS;const gradeRows=gradeBands.map((b,i)=>{const high=i===0?100:gradeBands[i-1].min-1;return `<tr><td>${primary?b.units:b.grade}</td><td>${b.min}-${high}%</td><td>${esc(primary?b.status:b.comment)}</td></tr>`}).join("");
    const gradingPage=`<section class="sheet"><header><img class="school-logo" src="${logo}" alt="Double Impact Private College"><div><h1>${school}</h1><h2>${primary?"Primary":"Secondary"} Grading Key</h2><p>${esc(data.term)} · ${esc(data.year)}</p></div></header><table><thead><tr><th>${primary?"UNITS":"GRADE"}</th><th>MINIMUM PERCENTAGE</th><th>DESCRIPTION</th></tr></thead><tbody>${gradeRows}</tbody></table><footer>ASSESSMENT GRADING REFERENCE</footer></section>`;
    openPrint(primary?"Primary Student Reports":"Secondary Student Reports",cover+anthem+pages+gradingPage,common+".cover{display:flex;flex-direction:column;justify-content:space-between}.anthem .flag{display:block;width:170px;height:auto;margin:8px auto 14px}.anthem-table td{width:50%;font-size:9px;line-height:1.25}.anthem-table th{font-size:9px}.cover-details{border:1px solid #aab6c4;background:#fff;padding:16px;line-height:1.8}.cover .school-logo{width:170px;height:auto}");
  }
  function settings(){title("Settings & backup","Settings");$("#view").innerHTML=`<div class="grid2"><div class="panel"><h3>Data protection</h3><p class="muted">Export a complete JSON backup containing students, subjects, examination settings and recorded marks. Store backups somewhere safe. The exam records are shared by staff with exam access.</p><button class="btn" id="export">Download backup</button><div class="field" style="margin-top:20px"><label>RESTORE FROM BACKUP</label><input id="importFile" type="file" accept="application/json"></div><button class="btn soft" id="import">Restore selected backup</button></div><div class="panel"><h3>Grading rules</h3><p class="muted">Primary units and Secondary grades are managed by the shared calculation module. The supplied school grading bands are included.</p><div class="notice">Primary 30–39% is now correctly classified as Pass; 20–29% is Fail.</div><div class="notice blue">Secondary pass threshold currently follows your supplied peach scale: E (30–39%) is Pass.</div><button class="btn ghost" style="background:var(--navy)" id="reset">Reset exam records</button></div></div>`;
    $("#export").onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`DIPvtC-backup-${data.year}-${data.term.replaceAll(" ","-")}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
    $("#import").onclick=()=>{const f=$("#importFile").files[0];if(!f){alert("Choose a backup file.");return}const r=new FileReader();r.onload=()=>{try{const incoming=JSON.parse(r.result);if(!Array.isArray(incoming.students)||!Array.isArray(incoming.subjects)||(incoming.attendance!==undefined&&!Array.isArray(incoming.attendance))||(incoming.reportComments!==undefined&&(!incoming.reportComments||typeof incoming.reportComments!=="object"||Array.isArray(incoming.reportComments)))||(incoming.fees!==undefined&&(!incoming.fees||typeof incoming.fees!=="object"||Array.isArray(incoming.fees)))||(incoming.openingDates!==undefined&&(!incoming.openingDates||typeof incoming.openingDates!=="object"||Array.isArray(incoming.openingDates))))throw Error("Invalid backup");if(!confirm("Restoring this backup replaces the shared exam records saved on the school server. Continue?"))return;data={...defaultData,...incoming};save();alert("Backup restored.");render()}catch{alert("That backup file is not valid.")}};r.readAsText(f)};
    $("#reset").onclick=()=>{if(confirm("This permanently clears the shared exam records on the school server. Export a backup first. Continue?")){data=structuredClone(defaultData);save();render()}};
  }
  async function optimizedSchoolImage(file,maxWidth,maxHeight){const image=await createImageBitmap(file);const scale=Math.min(1,maxWidth/image.width,maxHeight/image.height),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext("2d");ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,"image/webp",0.84));if(!blob)throw new Error("The image could not be prepared. Choose another PNG, JPEG or WebP file.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error("The image could not be read."));reader.readAsDataURL(blob)})}
  async function saveSchoolImage(status,message){save();if(typeof storage.flush==="function"){const ok=await storage.flush();status.textContent=ok?message:"The server did not confirm the save. Keep the page open and try again.";status.style.color=ok?"#176b43":"#a12626"}else{status.textContent=message;status.style.color="#176b43"}}
  function schoolSettings(){title("School details & schedule","School details");const key=data.year+"|"+data.term;$("#view").innerHTML='<div class="panel"><h3>School identity and contact information</h3><p class="muted">These details appear on report books and are stored with the server-side exam backup.</p><div class="form-row"><div class="field"><label>SCHOOL NAME</label><input id="schoolName" value="'+esc(data.school)+'"></div><div class="field"><label>ADDRESS</label><input id="schoolAddress" value="'+esc(data.schoolAddress||'')+'"></div></div><div class="form-row"><div class="field"><label>RECTANGULAR REPORT LOGO · LANDSCAPE</label><input id="schoolLogoUpload" type="file" accept="image/png,image/jpeg,image/webp"><small class="muted">Choose a wide logo; it is resized and saved to the server when selected.</small><small id="schoolLogoSaveStatus" class="muted" role="status" aria-live="polite"></small><img id="schoolLogoPreview" alt="Report logo preview" style="display:block;max-width:100%;width:420px;height:95px;object-fit:cover;object-position:center;background:#f8fafc;border:1px solid #dce4ee;border-radius:8px;padding:0;margin-top:6px"></div></div><div class="form-row"><div class="field"><label>SCHOOL APP ICON · OPTIONAL</label><input id="schoolIconUpload" type="file" accept="image/png,image/jpeg,image/webp"><small class="muted">Choose a logo; it is resized and saved to the server when selected. Without one, the DIP text remains visible.</small><small id="schoolIconSaveStatus" class="muted" role="status" aria-live="polite"></small><img id="schoolIconPreview" alt="School app icon preview" style="display:block;width:72px;height:72px;object-fit:cover;object-position:center;background:#fff;border:1px solid #dce4ee;border-radius:12px;padding:0;margin-top:6px"></div></div><div class="form-row three"><div class="field"><label>EMAIL</label><input id="schoolEmail" type="email" value="'+esc(data.schoolEmail||'')+'"></div><div class="field"><label>PHONE</label><input id="schoolPhone" value="'+esc(data.schoolPhone||'')+'"></div><div class="field"><label>WEBSITE</label><input id="schoolWebsite" value="'+esc(data.schoolWebsite||'')+'"></div></div></div><div class="panel" style="margin-top:16px"><h3>School fees and opening date</h3><p class="muted">Set the next-term fees and opening date for '+esc(data.term)+' '+esc(data.year)+'.</p><div class="form-row"><div class="field"><label>NEXT TERM SCHOOL FEES (include currency)</label><input id="schoolFees" value="'+esc(data.fees[key]||data.fees[data.term]||'')+'" placeholder="e.g. ZAR 250.00"></div><div class="field"><label>NEXT TERM OPENING DATE</label><input id="schoolOpening" type="date" value="'+esc(data.openingDates[key]||data.openingDates[data.term]||'')+'"></div></div><button class="btn" id="saveSchoolDetails">Save school details</button></div>';const iconPreview=$("#schoolIconPreview");if(data.schoolIcon){iconPreview.src=data.schoolIcon;iconPreview.hidden=false}else{iconPreview.removeAttribute("src");iconPreview.hidden=true}$("#schoolIconUpload").onchange=async()=>{const file=$("#schoolIconUpload").files[0],status=$("#schoolIconSaveStatus");if(!file)return;if(!["image/png","image/jpeg","image/webp"].includes(file.type)){status.textContent="Choose a PNG, JPEG or WebP icon.";return}status.textContent="Preparing and saving the school icon…";try{data.schoolIcon=await optimizedSchoolImage(file,512,512);iconPreview.src=data.schoolIcon;iconPreview.hidden=false;syncSchoolIcon();await saveSchoolImage(status,"School icon saved to the server.")}catch(error){status.textContent=error.message;status.style.color="#a12626"}};const logoPreview=$("#schoolLogoPreview");if(data.schoolLogo){logoPreview.src=data.schoolLogo;logoPreview.hidden=false}else{logoPreview.removeAttribute("src");logoPreview.hidden=true}$("#schoolLogoUpload").onchange=async()=>{const file=$("#schoolLogoUpload").files[0],status=$("#schoolLogoSaveStatus");if(!file)return;if(!["image/png","image/jpeg","image/webp"].includes(file.type)){status.textContent="Choose a PNG, JPEG or WebP report logo.";return}status.textContent="Preparing and saving the report logo…";try{data.schoolLogo=await optimizedSchoolImage(file,1600,440);data.savedReports.forEach(report=>{report.schoolLogo=data.schoolLogo});logoPreview.src=data.schoolLogo;logoPreview.hidden=false;await saveSchoolImage(status,"Report logo saved to the server.")}catch(error){status.textContent=error.message;status.style.color="#a12626"}};$("#saveSchoolDetails").onclick=()=>{data.school=$("#schoolName").value.trim()||defaultData.school;data.schoolAddress=$("#schoolAddress").value.trim();data.schoolEmail=$("#schoolEmail").value.trim();data.schoolPhone=$("#schoolPhone").value.trim();data.schoolWebsite=$("#schoolWebsite").value.trim();syncSchoolIcon();const k=data.year+"|"+data.term;data.fees[k]=$("#schoolFees").value.trim();data.openingDates[k]=$("#schoolOpening").value;data.students.filter(student=>data.savedReports.some(report=>report.reportKey===[student.id,data.year,data.term].join("|"))).forEach(student=>saveTermReport(student.id));save();alert("School details and schedule saved.")}}
